`timescale 1ns/1ps
// N-9 / NOC-3 unit bench for rtl/dual_lane/noc_l2_auth.sv (P6-S, PQ_MAC_ON). OFFLINE DEMO ONLY.
// Data-driven: every stimulus packet, every expected TX flit, every expected RX verdict, reject
// reason, NI delivery and transaction-slot state comes from vectors/l2_golden.svh, generated by
// scripts/l2_golden.py (teammate kmac128 adapter + M-F1 rev 6 R6.5-R6.8 spec model). The bench
// computes no expected value. Check count per mode: reports/i5_p3/P3_COUNT_DERIVATION.md.
// Modes: default ENFORCE; +define+L2_NEG_MAC / L2_NEG_SEQUENCE / L2_NEG_EPOCH (test-only bypass
// controls of noc_l2_auth). No identity bypass exists in the RTL (C-3).
module tb_noc_l2_auth;
 import noc_pkg::*;
`ifdef L2_NEG_MAC
 localparam bit NEG_MAC=1;
`else
 localparam bit NEG_MAC=0;
`endif
`ifdef L2_NEG_SEQUENCE
 localparam bit NEG_SEQUENCE=1;
`else
 localparam bit NEG_SEQUENCE=0;
`endif
`ifdef L2_NEG_EPOCH
 localparam bit NEG_EPOCH=1;
`else
 localparam bit NEG_EPOCH=0;
`endif
 localparam int MODE=NEG_MAC?1:NEG_SEQUENCE?2:NEG_EPOCH?3:0;   // l2_golden.py MODES order
 localparam int OP_RESET=0,OP_RX=1,OP_BURST=2,OP_TX=3,OP_PROBE=4,OP_INJECT=5;
 localparam int OBS=64, IDLE_BOUND=4000;
`include "l2_golden.svh"
 logic clk=0,rst=1;always #10 clk=~clk;
 logic [79:0] boot_epoch;
 logic [1535:0] tx_keys,rx_keys;
 logic tx_valid=0,tx_ready;
 coord_t tx_dest_coord;
 msg_type_e tx_msg_type;
 logic [10:0] tx_control;
 logic [31:0] tx_payload_data;
 logic tx_payload_valid=0,tx_payload_ready,tx_error;
 flit_t noc_tx_flit,noc_rx_flit;
 logic noc_tx_valid,noc_tx_ready=1,noc_rx_valid=0,noc_rx_ready;
 coord_t rx_src_coord,rx_dest_coord;
 msg_type_e rx_msg_type;
 logic [10:0] rx_control;
 logic [4:0] rx_length;
 logic rx_head_valid;
 logic [31:0] rx_payload_data;
 logic rx_payload_valid,rx_payload_last,rx_ready=1,rx_abort;
 logic [31:0] rejected_count,accepted_count;
 logic [3:0] reject_reason;
 logic tx_busy,rx_busy;
 noc_l2_auth #(.TILE(L2_TILE),.BYPASS_MAC(NEG_MAC),.BYPASS_SEQUENCE(NEG_SEQUENCE),.BYPASS_EPOCH(NEG_EPOCH)) dut(.*);

 int checks=0,errors=0,aborts=0;
 bit neg_effective=0;
 // Per-step observation of the NI application port and of the network TX port.
 int nh=0,np=0,nt=0;
 logic [31:0] head_obs[OBS];
 logic [31:0] pay_obs[OBS];
 flit_t tx_obs[OBS];
 always @(posedge clk) if(!rst) begin
   if(rx_head_valid&&rx_ready)begin
     if(nh<OBS)head_obs[nh]={rx_dest_coord.x,rx_dest_coord.y,rx_src_coord.x,rx_src_coord.y,rx_msg_type,rx_length,rx_control};
     nh++;
   end
   if(rx_payload_valid&&rx_ready)begin if(np<OBS)pay_obs[np]=rx_payload_data;np++;end
   if(noc_tx_valid&&noc_tx_ready)begin if(nt<OBS)tx_obs[nt]=noc_tx_flit;nt++;end
   if(rx_abort)aborts++;
 end

 task automatic check(input bit c,input string name);
   checks++;$display("[%s] %s",c?"PASS":"FAIL",name);if(!c)errors++;
 endtask
 // Bounded wait for both directions to go idle. A bound hit is an ERROR (never a pass), not a check.
 task automatic wait_idle(input string name);
   int n;n=0;
   repeat(3)@(negedge clk);
   while((rx_busy||tx_busy)&&n<IDLE_BOUND)begin @(negedge clk);n++;end
   if(rx_busy||tx_busy)begin errors++;$display("[ERROR] %s: WAIT_IDLE_BOUND reached",name);end
   repeat(3)@(negedge clk);
 endtask
 task automatic clear_obs;
   @(negedge clk);nh=0;np=0;nt=0;
 endtask
 // Drive one wire packet, one flit per cycle; noc_rx_ready is constant 1 (R6.7.1).
 task automatic drive_packet(input int p);
   for(int w=0;w<l2_pkt_len(p);w++)begin @(negedge clk);noc_rx_flit=l2_pkt_flit(p,w);noc_rx_valid=1;end
 endtask
 task automatic end_drive;
   @(negedge clk);noc_rx_valid=0;noc_rx_flit='0;
 endtask

 task automatic step_reset(input int s,input string name);
   @(negedge clk);rst=1;
   if(l2_step_arg(MODE,s)==1)begin boot_epoch=L2_BOOT_B;tx_keys=L2_TX_KEYS_B;rx_keys=L2_RX_KEYS_B;end
   else begin boot_epoch=L2_BOOT_A;tx_keys=L2_TX_KEYS_A;rx_keys=L2_RX_KEYS_A;end
   repeat(4)@(negedge clk);rst=0;repeat(2)@(negedge clk);
   check(accepted_count==0&&rejected_count==0&&reject_reason==l2_exp_reason(MODE,s)&&
         dut.ni.txn_valid_q==l2_exp_slots(MODE,s),{name,":RESET_STATE"});
 endtask

 // RX / BURST: 4 checks (counters, reason, NI delivery, slot state).
 task automatic step_rx(input int s,input string name,input bit burst);
   int a0,r0,ra,rr;bit ok;
   clear_obs();a0=accepted_count;r0=rejected_count;
   if(burst)for(int k=0;k<l2_step_burst(MODE,s);k++)drive_packet(l2_step_burst_pkt(MODE,s,k));
   else drive_packet(l2_step_arg(MODE,s));
   end_drive();wait_idle(name);
   ra=accepted_count-a0;rr=rejected_count-r0;
   // Burst: delivery is exact; drops are a lower bound only (C-6: per-packet overload counts not frozen).
   check(ra==l2_exp_acc(MODE,s)&&(l2_exp_rej_min(MODE,s)?rr>=l2_exp_rej(MODE,s):rr==l2_exp_rej(MODE,s)),
         $sformatf("%s:COUNTERS acc+%0d rej+%0d",name,ra,rr));
   check(reject_reason==l2_exp_reason(MODE,s),$sformatf("%s:REASON %0d",name,reject_reason));
   ok=nh==l2_exp_heads(MODE,s)&&np==l2_exp_pays(MODE,s)&&nt==0;
   for(int i=0;i<l2_exp_heads(MODE,s)&&i<OBS;i++)if(head_obs[i]!==l2_exp_head(MODE,s,i))ok=0;
   for(int i=0;i<l2_exp_pays(MODE,s)&&i<OBS;i++)if(pay_obs[i]!==l2_exp_pay(MODE,s,i))ok=0;
   check(ok,$sformatf("%s:NI_DELIVERY heads=%0d payloads=%0d tx=%0d",name,nh,np,nt));
   check(dut.ni.txn_valid_q==l2_exp_slots(MODE,s),$sformatf("%s:SLOTS %b",name,dut.ni.txn_valid_q));
   if(l2_step_attack(MODE,s)&&ok&&l2_exp_heads(MODE,s)>0)neg_effective=1;
 endtask

 // TX: 2 checks (every wire flit bit-exact vs oracle, slot state).
 task automatic step_tx(input int s,input string name);
   int t,n;bit ok;
   t=l2_step_arg(MODE,s);clear_obs();
   @(negedge clk);tx_dest_coord=tile_to_coord(tile_id_e'(l2_tx_dest(t)));tx_msg_type=msg_type_e'(l2_tx_msg(t));
   tx_control=l2_tx_ctl(t);tx_valid=1;
   n=0;do begin @(posedge clk);n++;end while(!tx_ready&&n<IDLE_BOUND);
   @(negedge clk);tx_valid=0;
   for(int i=0;i<l2_tx_npay(t);i++)begin
     tx_payload_data=l2_tx_pay(t,i);tx_payload_valid=1;
     n=0;do begin @(posedge clk);n++;end while(!tx_payload_ready&&n<IDLE_BOUND);
     @(negedge clk);
   end
   tx_payload_valid=0;
   wait_idle(name);
   ok=nt==l2_tx_len(t)&&nh==0;
   for(int w=0;w<l2_tx_len(t)&&w<OBS;w++)if(tx_obs[w]!==l2_tx_flit(t,w))ok=0;
   check(ok,$sformatf("%s:TX_WIRE_BIT_EXACT flits=%0d",name,nt));
   check(dut.ni.txn_valid_q==l2_exp_slots(MODE,s),$sformatf("%s:SLOTS %b",name,dut.ni.txn_valid_q));
 endtask

 // PROBE: 1 check. tx_ready must equal the oracle on every sampled cycle; drive=1 also offers the
 // request (a refused send must emit no flit).
 task automatic step_probe(input int s,input string name);
   bit ok;ok=1;clear_obs();
   @(negedge clk);tx_dest_coord=tile_to_coord(tile_id_e'(l2_step_arg(MODE,s)));tx_msg_type=msg_type_e'(l2_step_msg(MODE,s));
   tx_valid=l2_step_drive(MODE,s);
   repeat(20)begin @(posedge clk);if(tx_ready!==l2_exp_ready(MODE,s))ok=0;end
   @(negedge clk);tx_valid=0;
   if(l2_step_drive(MODE,s))wait_idle(name);
   check(ok&&nt==0,$sformatf("%s:TX_READY_IS_%0d tx=%0d",name,l2_exp_ready(MODE,s),nt));
 endtask

 // INJECT: explicit boundary-state injection (test-only; not a production reset/provisioning claim).
 task automatic step_inject(input int s,input string name);
   @(negedge clk);dut.tx_seq[l2_step_arg(MODE,s)]=l2_step_val(MODE,s);
   $display("[INFO] %s = %h",name,l2_step_val(MODE,s));
 endtask

 initial begin
   if(int'(NEG_MAC)+int'(NEG_SEQUENCE)+int'(NEG_EPOCH)>1)$fatal(1,"CONFIG: at most one L2_NEG_* define");
   $display("CONFIG: TOP=tb_noc_l2_auth TILE=%0d MODE=%0d NEG_MAC=%0d NEG_SEQUENCE=%0d NEG_EPOCH=%0d STEPS=%0d ORACLE=%s DEMO=1",
            L2_TILE,MODE,NEG_MAC,NEG_SEQUENCE,NEG_EPOCH,l2_n_steps(MODE),L2_ORACLE_ID);
   boot_epoch=L2_BOOT_A;tx_keys=L2_TX_KEYS_A;rx_keys=L2_RX_KEYS_A;
   tx_dest_coord='0;tx_msg_type=MSG_ATTEST_GRANT;tx_control=0;tx_payload_data=0;noc_rx_flit='0;
   for(int s=0;s<l2_n_steps(MODE);s++)begin
     string name;name=$sformatf("S%0d_%s",s,l2_step_name(MODE,s));
     case(l2_step_op(MODE,s))
       OP_RESET: step_reset(s,name);
       OP_RX:    step_rx(s,name,0);
       OP_BURST: step_rx(s,name,1);
       OP_TX:    step_tx(s,name);
       OP_PROBE: step_probe(s,name);
       OP_INJECT:step_inject(s,name);
       default:  begin errors++;$display("[ERROR] %s: unknown step op",name);end
     endcase
   end
   check(aborts==L2_EXP_ABORTS,$sformatf("NI_NO_ABORT aborts=%0d",aborts));
   if(MODE!=0&&neg_effective)$display("NEGATIVE_CONTROL_EFFECTIVE");
   $display("CHECKS : %0d",checks);$display("ERRORS : %0d",errors);$display("RESULT : %s",errors==0?"PASS":"FAIL");$finish;
 end
 initial begin #25ms;$fatal(1,"TB_TIMEOUT L2 unit");end
endmodule
